/**
 * Better Auth — browser client.
 *
 * Use in client components for sign-in / sign-up / magic link / wallet:
 *
 *   const { data, error } = await authClient.signIn.magicLink({
 *     email, callbackURL: "/dashboard",
 *   });
 *   await authClient.signIn.siwe({ walletAddress, chainId, message, signature });
 *   await authClient.signOut();
 *
 * The plugin surface is generated by `createAuthClient`; the calls match
 * Better Auth's React docs (https://better-auth.com/docs).
 *
 * baseURL is resolved at runtime:
 *   - Same-origin relative (default): uses the /api/auth/* proxy at
 *     app/src/app/api/auth/[...path]/route.ts. Recommended for production.
 *     Cookies are issued by the browser to the public host (oma-ai.com)
 *     and flow correctly between frontend and backend.
 *   - NEXT_PUBLIC_API_URL: explicit backend URL. Used in dev when you
 *     want to debug the API directly, but cookies are host-only and
 *     won't flow between ports. Prefer same-origin.
 */
import { createAuthClient } from "better-auth/react";
import {
	magicLinkClient,
	siweClient,
} from "better-auth/client/plugins";

function resolveBaseUrl(): string {
	// Browser — use the same-origin /api/auth/* proxy so cookies are
	// stored against the frontend origin (no cross-port cookie scoping).
	if (typeof window !== "undefined") {
		return `${window.location.origin}/api/auth`;
	}
	// SSR — fall back to the explicit API URL env (defaults to localhost:3001).
	// NEXT_PUBLIC_AUTH_BASE_URL can override for unusual deploys.
	const envBase =
		process.env.NEXT_PUBLIC_AUTH_BASE_URL ??
		process.env.NEXT_PUBLIC_API_URL ??
		"http://localhost:3001";
	return envBase.replace(/\/$/, "");
}

export const authClient = createAuthClient({
	baseURL: resolveBaseUrl(),
	plugins: [magicLinkClient(), siweClient()],
});

export const { signIn, signUp, signOut, useSession, getSession } = authClient;
